select d.status as status, count(*) as cnt
from meal_order d
where d.del_flag = '0'

    and d.status = #{status}


    and d.status in ('0', '1')


    and d.accept_user_id = #{acceptUserId}


    and exists (
        select 1 from meal_order_candidate c
        where c.order_id = d.order_id
          and c.user_id = #{candidateUserId}
          and c.status in ('0', '4')
    )

${params.dataScope}
group by d.status

